$:set -euo pipefail
test -f AGENTS.md
cat AGENTS.md >/dev/null
gh api repos/BestNameYet/Terminals/issues/3 --jq .body >/dev/null
gh auth setup-git
gh api repos/BestNameYet/Terminals/issues/comments/6747813826 --jq .body > /tmp/previous_scope_publish_comment.json
node <<'NODE'
const fs=require('fs');
const x=JSON.parse(fs.readFileSync('/tmp/previous_scope_publish_comment.json','utf8'));
if(x.runOn!=='$'||x.forWhom!=='GPT6_0000000247_scope_applicability_publish-Terminals')throw Error('Unexpected original command identity');
if(!x.whatPrompt.includes("ORIGINAL_USER_DRAFT_JSON")||!x.whatPrompt.includes("MODEL_UNCHANGED"))throw Error('Original command content missing');
fs.writeFileSync('/tmp/retry_scope_publication.sh',x.whatPrompt,'utf8');
NODE
bash -e -o pipefail /tmp/retry_scope_publication.sh
printf 'RETRY_REMOTE_COMMIT '; git rev-parse HEAD
